arguments.rule_content:
{
  "title": "Detect XMRig Mining Process on Linux Servers",
  "id": "example sigma-001",
  "status": "experimental",
  "description": "Detects execution of XMRig miner processes (e.g., systemd-helper) with high CPU usage or outbound connections to known mining pools.",
  "author": "SOC Team",
  "logsource": {
    "product": "linux",
    "service": "process_monitor"
  },
  "detection": {
    "selection": {
      "process_name|contains": "systemd-helper",
      "command_line|contains": "xmrig"
    },
    "high_cpu": {
      "cpu_usage|gte": 90
    },
    "network": {
      "dst_ip|contains": ["104.18.22.33", "pool.minexmr.com"]
    },
    "condition": "selection and (high_cpu or network)"
  },
  "falsepositives": ["Legitimate systemd-helper processes"],
  "level": "high"
}
